    PageColumn Page(string id){var view=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=Theme.Canvas,Visible=false};var p=new PageColumn();view.Controls.Add(p);content.Controls.Add(view);pages[id]=view;return p;}
