    static PageColumn Labeled(string label,Control value){var p=new PageColumn{Dock=DockStyle.None,Padding=Padding.Empty,Width=value.Width};p.Add(Theme.Text(label,10,Theme.Muted),5);p.Add(value,0);return p;}
    static PageColumn Notice(string title,string text){var p=new PageColumn{BackColor=Theme.Surface,Padding=new Padding(16,12,16,10)};p.Add(Theme.Text(title,11,Theme.Gold,FontStyle.Bold),4);p.Add(Theme.Text(text,10,Theme.Muted),0);return p;}
    void ShowPage(string page){foreach(var p in pages)p.Value.Visible=p.Key==page;pages[page].BringToFront();foreach(var nav in navigation){nav.Value.Selected=nav.Key==page;nav.Value.Invalidate();}navigation[page].Focus();if(page=="guide")RenderGuide();}
    void OpenGuide(int topic){guideTopics.SelectedIndex=topic;ShowPage("guide");}
    void RenderGuide(){guideBody.SuspendLayout();foreach(Control old in guideBody.Controls.Cast<Control>().ToArray())old.Dispose();guideBody.Controls.Clear();guideBody.RowStyles.Clear();guideBody.RowCount=0;
        if(guideTopics.SelectedIndex==3){guideBody.Add(Theme.Text("Current game controls",15,null,FontStyle.Bold),8);var keys=Install.GetIni("KeyMap","Controls","Up, Down, Left, Right, Right Shift, Return, x, z, s, a, c, v").Split(',');string[] actions=["Move up","Move down","Move left","Move right","Select / save menu","Start / inventory","A · action / dash","B · sword","X · map","Y · equipped tool","L","R"];
            var pads=Install.GetIni("GamepadMap","Controls","DpadUp, DpadDown, DpadLeft, DpadRight, Back, Start, B, A, Y, X, Lb, Rb").Split(',');var table=new TableLayoutPanel{AutoSize=true,ColumnCount=3,RowCount=actions.Length+1,Margin=Padding.Empty};table.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,220));table.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,160));table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));table.Controls.Add(Theme.Text("Action",10,Theme.Gold,FontStyle.Bold),0,0);table.Controls.Add(Theme.Text("Keyboard",10,Theme.Gold,FontStyle.Bold),1,0);table.Controls.Add(Theme.Text("Controller",10,Theme.Gold,FontStyle.Bold),2,0);
            for(int i=0;i<actions.Length;i++){var action=Theme.Text(actions[i],11,Theme.Muted);var key=Theme.Text(i<keys.Length&&!string.IsNullOrWhiteSpace(keys[i])?keys[i].Trim():"Unassigned",11,null,FontStyle.Bold);var pad=Theme.Text(i<pads.Length&&!string.IsNullOrWhiteSpace(pads[i])?pads[i].Trim():"Unassigned",11,null,FontStyle.Bold);key.MaximumSize=new Size(156,0);pad.MaximumSize=new Size(240,0);action.Margin=key.Margin=pad.Margin=new Padding(0,0,0,3);table.Controls.Add(action,0,i+1);table.Controls.Add(key,1,i+1);table.Controls.Add(pad,2,i+1);}guideBody.Add(table,16);guideBody.Add(Theme.Text($"Fullscreen: {Install.GetIni("KeyMap","Fullscreen","Alt+Return")}   ·   Pause: {Install.GetIni("KeyMap","PauseDimmed","p")}\nTurbo: {Install.GetIni("KeyMap","Turbo","Tab")}",11,Theme.Muted),22);}
        foreach(var s in GuideContent.Sections(guideTopics.SelectedIndex)){guideBody.Add(Theme.Text(s.Title,15,null,FontStyle.Bold),6);guideBody.Add(Theme.Text(s.Body,11,Theme.Muted),22);}guideBody.ResumeLayout(true);}
    void SetRole(bool value){hosting=value;hostMode.Selected=value;joinMode.Selected=!value;hostMode.Invalidate();joinMode.Invalidate();if(bridge==null)connection.SelectedIndex=value?0:2;UpdateOnline();}
    void UpdateOnline(){onlineSetup.Visible=roleRow.Visible=onlineActions.Visible=bridge==null;connectionField.Visible=hosting;roomField.Visible=!hosting&&bridge==null;serverField.Visible=connection.SelectedIndex==2;create.Visible=hosting;join.Visible=!hosting;invitePanel.Visible=bridge!=null;disconnect.Visible=bridge!=null;connectionHint.Text=connection.SelectedIndex switch{0=>"Friends in different homes? We create an Internet link for you, including on Starlink.\nCloudflare carries presence traffic. Free testing service; no uptime guarantee.",1=>"Host on this network. Your friend needs your LAN address and room code.",_=>"Paste the relay address from your friend's invitation.\nInternet invitations start with wss://. No router changes are needed."};Enable();UpdateInvitation();}
    void UpdateLook(){lookDescription.Text=display.SelectedIndex switch{0=>"Recommended for your 1080p screen. Smooth xBRZ edges and a wide 16:9 view.",1=>"Sharp original pixel art, a wide 16:9 view and no smoothing shader.",_=>"Original 4:3 proportions, sharp pixels and side borders on a wide screen."};lookOnline.Text=$"Look: {display.SelectedItem}. Change it on Play; everyone needs the same choice.";}
    void UpdateReady(){playTitle.Text=Install.Ready?"A Link to the Past":"Your adventure starts here";playIntro.Text=Install.Ready?"Smooth graphics. Original adventure. Ready when you are.":"Bring your own original USA ROM. We’ll prepare the game on this PC.";readiness.Text=Install.Ready?"Game data ready · Windows x64":"1. Extract the ZIP   2. Choose ROM   3. Launch solo";import.Text=Install.Ready?"Change ROM…":"Choose ROM…";import.Primary=!Install.Ready;solo.Visible=Install.Ready;import.Invalidate();}
    void Enable(){bool playing=game is {HasExited:false};import.Enabled=!busy&&!playing&&bridge==null;solo.Enabled=!busy&&!playing&&Install.Ready;create.Enabled=join.Enabled=!busy&&!playing&&bridge==null&&Install.Ready;host.Enabled=!busy&&bridge==null;disconnect.Enabled=!busy&&bridge!=null;url.Enabled=code.Enabled=name.Enabled=tools.Enabled=sharedCombat.Enabled=campaign.Enabled=connection.Enabled=hostMode.Enabled=joinMode.Enabled=!busy&&bridge==null;onlineSeed.Enabled=!busy&&!playing&&bridge==null;showNames.Enabled=!busy&&!playing;display.Enabled=!busy&&!playing;saveSettings.Enabled=audio.Enabled=dimFlashes.Enabled=editControls.Enabled=!busy&&!playing;music.Enable(!busy&&!playing);randomizer.Enable(!busy&&!playing&&bridge==null);copyInvite.Enabled=!busy&&bridge is {IsConnected:true};help.Text=busy?"Cancel":"Help";UpdateReady();Cursor=busy?Cursors.WaitCursor:Cursors.Default;}
    async Task Guard(Func<Task> work){if(busy)return;operation=new CancellationTokenSource();busy=true;Enable();try{await work();}catch(Exception e){if(operation.IsCancellationRequested){SetStatus("Cancelled","The operation stopped. Your existing saves are unchanged.");}else{Log("Error: "+e.Message);SetStatus("Something needs attention",FriendlyError(e),true);}}finally{operation.Dispose();operation=null;busy=false;Enable();if(closeAfterWork)Close();}}
    static string FriendlyError(Exception e)=>e.Message=="Room not found."?"Ask the host for a fresh invitation and check both the relay address and room code. Empty rooms expire when everyone leaves.":e is OperationCanceledException?"Connection timed out. Check the relay address and ask the host for a new invitation.":e is System.Net.WebSockets.WebSocketException?"Could not reach the relay. Check its address and whether the host is running. Details are in Activity.":e.Message.Length>240?e.Message[..237]+"…":e.Message;
    void SetStatus(string title,string message,bool error=false){statusTitle.Text=title;statusTitle.ForeColor=error?Theme.Danger:Theme.Gold;status.Text=message;status.ForeColor=error?Theme.Danger:Theme.Muted;}
    void Log(string message){lock(logGate)File.AppendAllText(logPath,DateTime.UtcNow.ToString("O")+" "+message+Environment.NewLine);if(IsDisposed||Disposing)return;void Append(){if(output.TextLength>28000)output.Text=output.Text[^14000..];output.AppendText(message+Environment.NewLine);}if(InvokeRequired)BeginInvoke((Action)Append);else Append();}
    void SavePreferences(){preferences.Look=display.SelectedIndex;preferences.PlayerName=name.Text.Trim();preferences.ShareTools=tools.Checked;preferences.SharedCombat=sharedCombat.Checked;preferences.ShowNames=showNames.Checked;try{preferences.Save();}catch(Exception e){Log("Could not save preferences: "+e.Message);}}
    static void EnsureReady(){if(!Install.Ready)throw new IOException("Choose your original USA ROM on the Play page first.");}
    sealed record OnlineSeedItem(ShuffleRecipe? Recipe){public override string ToString()=>Recipe==null?"Original adventure":$"Treasure Shuffle · {Recipe.Seed} · {Recipe.Id[..8]}";}
    ShuffleRecipe? SelectedOnlineSeed => (onlineSeed.SelectedItem as OnlineSeedItem)?.Recipe;
    void RefreshOnlineSeeds(string? id=null){id??=SelectedOnlineSeed?.Id;onlineSeed.Items.Clear();onlineSeed.Items.Add(new OnlineSeedItem(null));onlineSeed.Items.AddRange(shuffle.List().Select(r=>new OnlineSeedItem(r)).ToArray());onlineSeed.SelectedIndex=Enumerable.Range(0,onlineSeed.Items.Count).FirstOrDefault(i=>((OnlineSeedItem)onlineSeed.Items[i]!).Recipe?.Id==id);}
    void RefreshCampaigns(){campaign.Items.Clear();campaignIds.Clear();campaignIds.Add(null);campaign.Items.Add("New co-op campaign");foreach(var saved in Install.SavedCampaigns(SelectedOnlineSeed?.Id)){campaignIds.Add(saved.Id);campaign.Items.Add($"Continue · {saved.Saved.ToLocalTime():MMM d, h:mm tt}");}int previous=campaignIds.IndexOf(preferences.LastCampaignId);campaign.SelectedIndex=previous>0?previous:campaignIds.Count>1?1:0;}
    Task LaunchSeed(ShuffleRecipe recipe){EnsureReady();if(game is {HasExited:false}||bridge!=null)throw new IOException("Save and close the current game before launching another seed.");shuffle.Verify(recipe.Id);ApplyDisplay();shuffle.Backup(recipe.Id);string dir=Path.Combine(shuffle.SeedFolder(recipe.Id),"Game");foreach(string file in new[]{"zelda3.exe","SDL2.dll"})File.Copy(Path.Combine(Install.Game,file),Path.Combine(dir,file),true);Install.CopyTree(Path.Combine(Install.Game,"glsl-shaders"),Path.Combine(dir,"glsl-shaders"));string ini=Path.Combine(dir,"zelda3.ini");if(File.Exists(ini))File.Copy(ini,ini+".previous",true);File.Copy(Path.Combine(Install.Game,"zelda3.ini"),ini,true);LaunchGame(dir,"zelda3.exe",null);SetStatus("Treasure Shuffle running",$"Seed: {recipe.Seed}. Saves and backups stay in this seed's own folder.");Log("Started verified Treasure Shuffle v1 identity "+recipe.Id);return Task.CompletedTask;}
    static void BackupSettings(string ini){string folder=Path.Combine(Install.Data,"SettingsBackups");Directory.CreateDirectory(folder);File.Copy(ini,Path.Combine(folder,DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff")+".ini"));}
    void ApplyDisplay(){string ini=Path.Combine(Install.Game,"zelda3.ini");BackupSettings(ini);Install.SetIni(ini,"Graphics","Shader",display.SelectedIndex==0?"glsl-shaders/xbrz/xbrz-freescale.glslp":"");Install.SetIni(ini,"Graphics","OutputMethod",display.SelectedIndex==0?"OpenGL":"SDL");Install.SetIni(ini,"Graphics","Fullscreen","1");Install.SetIni(ini,"General","ExtendedAspectRatio",display.SelectedIndex==2?"4:3":"16:9");SavePreferences();}
    async Task StartRelay(bool lan=false,bool automatic=false){string bind=relayBind=="http://127.0.0.1:24816"?(lan?"http://0.0.0.0:24816":automatic?"http://127.0.0.1:0":relayBind):relayBind;relay=new Relay(bind,Log);try{await relay.Start();}catch{await relay.DisposeAsync();relay=null;throw;}host.Text="Stop local relay";SetStatus("Local relay running","Keep the launcher open while hosting. Internet mode uses an outbound connection.");}
    async Task Connect(string action){EnsureReady();if(string.IsNullOrWhiteSpace(name.Text))throw new ArgumentException("Enter your name on the Online page.");if(action=="join"&&(code.Text.Trim().Length!=16||!code.Text.Trim().All(Uri.IsHexDigit)))throw new ArgumentException("Enter your friend's 16-character room code. Ask them to use Copy invitation.");if(!Uri.TryCreate(url.Text.Trim(),UriKind.Absolute,out var uri)||uri.Scheme is not("ws" or "wss"))throw new ArgumentException("Enter a relay address: ws://HOST-LAN-IP:24816/room or wss://YOUR-SERVER/room.");SetStatus("Connecting","Checking room, game data and matching settings…");ApplyDisplay();var next=new Bridge(Log);
        try{var seed=SelectedOnlineSeed;if(seed!=null)shuffle.Verify(seed.Id);string asset=seed==null?Path.Combine(Install.Game,"zelda3_assets.dat"):shuffle.AssetPath(seed.Id);await next.Connect(url.Text.Trim(),new Hello(action,code.Text.Trim(),name.Text.Trim(),Protocol.Build,Protocol.HashFile(asset),Install.GameplayHash(),tools.Checked,sharedCombat.Checked),operation?.Token??default);bridge=next;code.Text=next.Welcome.Code;operation?.Token.ThrowIfCancellationRequested();string profile=Install.OnlineProfile(url.Text.Trim(),code.Text,campaignIds[campaign.SelectedIndex],seed?.Id);LaunchGame(profile,"online.exe",next);preferences.LastCampaignId=Path.GetFileName(profile);SavePreferences();UpdateOnline();UpdateInvitation();SetStatus("Online game started",$"Player {next.Welcome.Slot}: {Protocol.ColorName(next.Welcome.Slot)}. Your invitation is on Online. Save before closing.");}catch{if(bridge==next)bridge=null;await next.DisposeAsync();UpdateOnline();throw;}}
    void LaunchGame(string dir,string exe,Bridge? session){new SoundtrackLibrary(Install.Data).PrepareForLaunch(dir,Log);var info=new ProcessStartInfo(Path.Combine(dir,exe)){WorkingDirectory=dir,UseShellExecute=false,RedirectStandardError=true,RedirectStandardOutput=true,CreateNoWindow=true};if(session!=null){info.Environment["Z3ONLINE_PORT"]=session.Port.ToString();info.Environment["Z3ONLINE_TOKEN"]=session.Token.ToString("x8");info.Environment["Z3ONLINE_SLOT"]=session.Welcome.Slot.ToString();info.Environment["Z3ONLINE_NAME"]=session.PlayerName;info.Environment["Z3ONLINE_COMBAT"]=session.SharedCombat?"1":"0";info.Environment["Z3ONLINE_LABELS"]=showNames.Checked?"1":"0";}var p=Process.Start(info)??throw new IOException("Game did not start. Open Activity for details.");game=p;
        _=Task.Run(async()=>{async Task Pump(StreamReader s){while(await s.ReadLineAsync() is {} line)Log(line);}await Task.WhenAll(Pump(p.StandardError),Pump(p.StandardOutput),p.WaitForExitAsync());int result=p.ExitCode;if(!IsDisposed)BeginInvoke((Action)(async()=>{Log("Game closed, exit "+result);if(session!=null&&session==bridge)await Disconnect();game=null;p.Dispose();Enable();SetStatus(result==0?"Game closed":"Game exited with an error",result==0?"The launcher is ready. Saved progress remains in its own folder.":"Open Activity and Logs for details before trying again.",result!=0);}));});Log(session==null?"Solo game started.":"Online game started in its private campaign. Eight-player co-op protocol; names enabled: "+showNames.Checked+"; combat beta: "+session.SharedCombat);if(session==null)SetStatus("Solo game running","Save in the game before closing. The launcher will be ready when you return.");Enable();}
    async Task Disconnect(){if(bridge!=null){var b=bridge;bridge=null;await b.DisposeAsync();Log("Disconnected. Game can continue in its private online campaign.");SetStatus("Disconnected","Your game can continue solo in this online campaign. Save before closing.");}if(internet!=null){await internet.DisposeAsync();internet=null;url.Text="";if(relay!=null){await relay.DisposeAsync();relay=null;host.Text="Start local relay";}Log("Your hosted Internet link has closed. Friends will need a new invitation.");}UpdateOnline();Enable();}
    void LoadLanAddresses(){var addresses=NetworkInterface.GetAllNetworkInterfaces().Where(n=>n.OperationalStatus==OperationalStatus.Up&&n.NetworkInterfaceType!=NetworkInterfaceType.Loopback).OrderByDescending(n=>n.GetIPProperties().GatewayAddresses.Any()).SelectMany(n=>n.GetIPProperties().UnicastAddresses).Where(a=>a.Address.AddressFamily==AddressFamily.InterNetwork&&!a.Address.ToString().StartsWith("169.254.")).Select(a=>a.Address.ToString()).Distinct().ToArray();lanAddress.Items.AddRange(addresses.Length>0?addresses:["No LAN address found"]);lanAddress.SelectedIndex=0;}
    string InvitationText(){string address=internet?.RelayUrl??url.Text.Trim();bool lan=connection.SelectedIndex==1;if(lan&&lanAddress.SelectedItem is string ip&&System.Net.IPAddress.TryParse(ip,out _))address=$"ws://{ip}:24816/room";var seed=SelectedOnlineSeed;string adventure=seed==null?"Original adventure":$"Treasure Shuffle v1 · {seed.Seed} · {seed.Options.Style} · Hearts: {seed.Options.HeartPieces} · ID {seed.Id}";return $"Zelda Companion 0.3.1 · up to 8 players\r\nRelay: {address}\r\nRoom: {bridge?.Welcome.Code??code.Text}\r\nAdventure: {adventure}\r\nLook: {display.SelectedItem} · Shared progress: {(tools.Checked?"Yes":"No")} · Combat beta: {(sharedCombat.Checked?"Yes":"No")}\r\nUse Online → Join a room. Everyone needs 0.3.1 and the same adventure. {(seed==null?"":"Import the Companion seed recipe first. ")}{(lan?"Same network only.":"Keep the host launcher open. This link is temporary.")}";}
    void UpdateInvitation(){if(bridge==null)return;invitation.Text=InvitationText();lanField.Visible=connection.SelectedIndex==1;copyInvite.Enabled=!busy&&bridge.IsConnected;}
    void SafeOpen(string path,bool directory=false,bool editor=false){try{if(directory)Directory.CreateDirectory(path);if(editor)Process.Start(new ProcessStartInfo("notepad.exe"){ArgumentList={path},UseShellExecute=true});else Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}catch(Exception e){SetStatus("Could not open that file",e.Message,true);Log(e.Message);}}
}
